import{_ as d,a}from"./chunks/image-20261116062042218.D9BasGho.js";import{_ as r,o as e,c as i,a2 as o}from"./chunks/framework.CmPiTyN0.js";const g=JSON.parse('{"title":"模块化损伤","description":"","frontmatter":{"title":"模块化损伤","outline":"deep"},"headers":[],"relativePath":"wiki/damage.md","filePath":"wiki/damage.md","lastUpdated":null}'),p={name:"wiki/damage.md"};function s(_,t,n,l,m,c){return e(),i("div",null,[...t[0]||(t[0]=[o('<p><a href="./../index.html">← 返回 Wiki 首页</a></p><h2 id="_7-模块化损伤" tabindex="-1">7. 模块化损伤 <a class="header-anchor" href="#_7-模块化损伤" aria-label="Permalink to &quot;7. 模块化损伤&quot;">​</a></h2><p>RVP 的损伤按部位和模块结算。不同部位具有独立耐久、伤害倍率和失效效果。</p><table tabindex="0"><thead><tr><th>部位/模块</th><th>失效效果</th></tr></thead><tbody><tr><td>ERA 爆反</td><td>被击穿后该块失效，失去防护弹药能力，外观同步变化</td></tr><tr><td>发动机</td><td>受损严重时失去大量动力，极速减半；<br>被彻底摧毁时失去全部动力无法移动。</td></tr><tr><td>炮管</td><td>受损严重时射击有概率失败，甚至炸膛，即使射击成功也会导致精度大幅度下降；<br>被彻底摧毁时无法射击。</td></tr><tr><td>方向机</td><td>受损严重时方向机转速大幅度下降；<br>彻底损坏时无法转动方向机</td></tr><tr><td>火控系统（FCS）</td><td>损坏后稳定器损坏、弹道解算与 CCIP 停止、热成像/夜视与光电搜索不可用；</td></tr><tr><td>雷达</td><td>被击毁后无法搜索/跟踪目标</td></tr><tr><td>APS/干扰机/DIRCM/干扰弹发射器</td><td>被击毁后失去对应功能</td></tr><tr><td>维修设备</td><td>被击毁后无法使用快速维修</td></tr></tbody></table><p>损伤计算使用部位 OBB 与独立伤害倍率；爆炸方向、入射角、装甲减伤参数、距离、弹种和 ERA 状态都会影响最终伤害。</p><p>维修面板按优先级恢复部件；可分别设置爆反维修顺序与辅助设备维修顺序。</p><p><img src="'+d+'" alt="image-20261116061921646"></p><p><img src="'+a+'" alt="image-20261116062042218"><strong>图7.1/7.2 损坏严重的坦克</strong></p><hr>',9)])])}const b=r(p,[["render",s]]);export{g as __pageData,b as default};
